package com.bank.loan;

import java.math.BigDecimal;

class Account {
    private final String accountId;
    private final BigDecimal balance;
    // Integer (not int) so it can be null = "no credit score on file".
    private final Integer creditScore;

    Account(String accountId, BigDecimal balance, Integer creditScore) {
        this.accountId = accountId;
        this.balance = balance;
        this.creditScore = creditScore; // may be null
    }

    String getAccountId() { return accountId; }
    Integer getCreditScore() { return creditScore; } // nullable
}
