package com.bank.loan;

class EligibilityService {

    // CORRECT: handle null, then compare by VALUE (unbox or use equals).
    boolean meetsThreshold(Account account, int threshold) {
        Integer score = account.getCreditScore();
        if (score == null) {
            return false; // no score on file → not eligible
        }
        return score >= threshold; // auto-unbox to int for numeric compare
    }

    // WRONG: == on boxed Integers compares references, not values.
    boolean sameScoreByReference(Integer a, Integer b) {
        return a == b; // works by luck only within the -128..127 cache
    }

    // CORRECT: equals compares value regardless of cache.
    boolean sameScoreByValue(Integer a, Integer b) {
        return a != null && a.equals(b);
    }
}
