package com.bank.loan;

import java.math.BigDecimal;
import java.util.logging.*;

public class WrapperDemo {
    private static final Logger log = Logger.getLogger(WrapperDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        EligibilityService svc = new EligibilityService();

        // 1) parseInt returns a primitive int (for arithmetic).
        int scoreInt = Integer.parseInt("720");
        log.info(() -> "parseInt(\"720\") -> primitive int " + scoreInt);

        // 2) valueOf returns an Integer object (for nullable fields / collections).
        Integer scoreObj = Integer.valueOf("720");
        log.info(() -> "valueOf(\"720\") -> Integer object " + scoreObj);

        // 3) Integer cache: small values are shared, large values are not.
        Integer small1 = Integer.valueOf(100), small2 = Integer.valueOf(100);
        Integer big1 = Integer.valueOf(1000), big2 = Integer.valueOf(1000);
        log.info(() -> "100 == 100 (cached) ? " + (small1 == small2));
        log.warning(() -> "1000 == 1000 (NOT cached) ? " + (big1 == big2)
                + " — use equals, not ==!");
        log.info(() -> "1000 .equals 1000 ? " + big1.equals(big2));

        // 4) Nullable credit score distinguishes 'no score' from zero.
        Account withScore = new Account("SAV2001", new BigDecimal("1000000"), 720);
        Account noScore = new Account("CUR3001", new BigDecimal("250000"), null);
        log.info(() -> "SAV2001 eligible (>=700)? " + svc.meetsThreshold(withScore, 700));
        log.info(() -> "CUR3001 eligible (>=700)? " + svc.meetsThreshold(noScore, 700)
                + " (null score → not eligible, NOT treated as 0)");

        // 5) The comparison bug and the fix on realistic scores.
        log.warning(() -> "sameScoreByReference(720,720): "
                + svc.sameScoreByReference(720, 720) + " (BUG for >127)");
        log.info(() -> "sameScoreByValue(720,720): "
                + svc.sameScoreByValue(720, 720) + " (CORRECT)");
    }
}

